//! Parity gate against the pypiqe 1.2 oracle: `tests/goldens_piqe.tsv`
//! holds `(path, score)` rows regenerated by `tests/golden_piqe.py`. Every
//! golden must land within `JND/1000` of [`piqe::JND`]; the worst absolute
//! delta and the worst delta in JND units are printed. Paths are relative
//! to `$ZENMETRICS_NR_GOLDEN_ROOT` (default `~/tmp`).

use piqe::{JND, Piqe};
use std::io::BufRead;
use za::zenpixels::{PixelDescriptor, PixelSlice};
use za::{EvalOpts, Image, NoReferenceMetric};
use zenmetrics_abstractions as za;

fn golden_root() -> std::path::PathBuf {
    std::env::var_os("ZENMETRICS_NR_GOLDEN_ROOT")
        .map(std::path::PathBuf::from)
        .unwrap_or_else(|| std::path::PathBuf::from(std::env::var("HOME").unwrap()).join("tmp"))
}

fn score_path(path: &std::path::Path) -> f64 {
    let path = &path.display().to_string();
    let img = image::open(path)
        .unwrap_or_else(|e| panic!("decode {path}: {e}"))
        .to_rgb8();
    let (w, h) = img.dimensions();
    let slice = PixelSlice::new(&img, w, h, w as usize * 3, PixelDescriptor::RGB8_SRGB).unwrap();
    Piqe::new()
        .evaluate_image(Image::from(slice), EvalOpts::new())
        .unwrap_or_else(|e| panic!("piqe {path}: {e}"))
        .score()
}

#[test]
fn matches_pypiqe_goldens() {
    let tsv = std::fs::File::open(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/goldens_piqe.tsv"
    ))
    .expect("goldens_piqe.tsv (regenerate with tests/golden_piqe.py)");
    let root = golden_root();
    let tol = JND * 1e-3;
    let mut n = 0usize;
    let mut worst_abs = 0.0f64;
    for line in std::io::BufReader::new(tsv).lines() {
        let line = line.unwrap();
        if line.starts_with('#') || line.is_empty() {
            continue;
        }
        let (path, expected) = line.split_once('\t').unwrap();
        let expected: f64 = expected.parse().unwrap();
        let got = score_path(&root.join(path));
        let d = (got - expected).abs();
        assert!(
            d <= tol,
            "{path}: expected {expected}, got {got} (|Δ|={d} > {tol} = JND/1000)"
        );
        worst_abs = worst_abs.max(d);
        n += 1;
    }
    assert_eq!(n, 42 + 128, "goldens row count changed — regenerate");
    eprintln!(
        "piqe parity: {n} goldens, worst |Δ| = {worst_abs:.3e} absolute = {:.3e} JND",
        worst_abs / JND
    );
}
